    gacc_abbrevs = ["AICC", "NRCC", "NWCC", "RMCC", "SACC", "SWCC", "ONCC", "OSCC", "EACC", "GBCC"]
    found = [a for a in gacc_abbrevs if re.search(r'\b' + a + r'\b', llm_output, re.IGNORECASE)]
